                    </>
                )}
            </View>
            <FixedFooter>
                <Button
                    success
                    large
                    text={translate('exitSurvey.goToExpensifyClassic')}
                    onPress={() => {
                        const promise = ExitSurvey.switchToOldDot();
                        if (NativeModules.HybridAppModule) {
